// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Attacker atk;

    function setUp() public {
        c = new ReentrancyDAO();
        atk = new Attacker(c);
    }

    function testFuzz_property(uint256 d, uint256 e, address other) public {
        d = bound(d, 1, 1 ether);
        e = bound(e, d, 2 ether);
        vm.assume(other != address(c) && other != address(atk) && other != address(this));

        vm.deal(address(atk), d);
        atk.deposit(d);

        vm.deal(other, e);
        vm.prank(other);
        c.deposit{value: e}();

        uint256 before = address(atk).balance;
        atk.attack();
        uint256 received = address(atk).balance - before;

        // Rule: a re-entrant caller can never extract more ether than its credited deposit.
        assertTrue(received <= d);
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool reentered;

    constructor(ReentrancyDAO _c) { c = _c; }

    function deposit(uint256 amt) external payable {
        c.deposit{value: amt}();
    }

    function attack() external {
        reentered = false;
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}
